  - exact bootq_1RB1LC_0LC0RB_1LA0LD_1RA0RB.
  - intros p _. apply lap_1RB1LC_0LC0RB_1LA0LD_1RA0RB.
  - intros t Ht p _. apply fire_1RB1LC_0LC0RB_1LA0LD_1RA0RB. exact Ht.
  - exact wit_1RB1LC_0LC0RB_1LA0LD_1RA0RB.
